-- Read-only installation audit; expect 8 PASS.
WITH checks AS (
 SELECT 'reservation trigger installed' check_name,EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.client_invoices'::regclass AND tgname='invoice_number_reserve_062' AND tgenabled='O' AND tgfoid='public.reserve_invoice_number_062()'::regprocedure) ok
 UNION ALL SELECT 'renumbering releases previous reservation',position('DELETE FROM invoice_numbers_062 WHERE number=OLD.invoice_number' IN pg_get_functiondef('public.reserve_invoice_number_062()'::regprocedure))>0
 UNION ALL SELECT 'no stale reservations',NOT EXISTS(SELECT 1 FROM public.invoice_numbers_062 r WHERE NOT EXISTS(SELECT 1 FROM public.client_invoices i WHERE i.id=r.invoice_id AND i.invoice_number=r.number))
 UNION ALL SELECT 'all current numbers reserved',NOT EXISTS(SELECT 1 FROM public.client_invoices i WHERE i.invoice_number IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.invoice_numbers_062 r WHERE r.invoice_id=i.id AND r.number=i.invoice_number))
 UNION ALL SELECT 'reservation table protected',NOT has_table_privilege('authenticated','public.invoice_numbers_062','INSERT') AND NOT has_table_privilege('authenticated','public.invoice_numbers_062','DELETE') AND (SELECT relrowsecurity FROM pg_class WHERE oid='public.invoice_numbers_062'::regclass)
 UNION ALL SELECT 'trigger function not callable',NOT has_function_privilege('authenticated','public.reserve_invoice_number_062()','EXECUTE') AND NOT has_function_privilege('anon','public.reserve_invoice_number_062()','EXECUTE')
 UNION ALL SELECT 'next-number selection skips used numbers',position('public.invoice_next_free_number_071(n+1)' IN pg_get_functiondef('public.invoice_issue_061(uuid,integer)'::regprocedure))>0 AND position('public.invoice_next_free_number_071(n+1)' IN pg_get_functiondef('public.invoice_revise_062(uuid,integer,jsonb,text)'::regprocedure))>0 AND NOT has_function_privilege('authenticated','public.invoice_next_free_number_071(bigint)','EXECUTE') AND NOT has_function_privilege('anon','public.invoice_next_free_number_071(bigint)','EXECUTE')
 UNION ALL SELECT 'finance and history remain protected',NOT has_table_privilege('authenticated','public.client_invoices','UPDATE') AND NOT has_table_privilege('authenticated','public.invoice_revisions_062','DELETE')
) SELECT check_name,CASE WHEN ok THEN 'PASS' ELSE 'FAIL' END result FROM checks ORDER BY check_name;
